"""Packs the fetched stages (out/stages/, from fetch.py and morpho_events.py) into the two committed fixtures:
  - protocols/substreams/base-flamm/testdata/e2e_blocks.json.gz: the real inputs (headers, the tracked-word
    diffs, the transactions of interest with their receipt logs, the created contracts' runtime code) and, at the
    pinned blocks, the full tracked state;
  - ../snapshots/e2e_grids.json.gz (this crate's testdata): the chain's answers at the pinned blocks
    (previewSwap / previewLever grids, edges, spot) and the pool's settled swaps decoded from their receipts.
Deterministic gzip (mtime 0); prints the sha256 digests for the README / fixture tables."""
import gzip, hashlib, io, json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from rpc import keccak256
from fetch import STAGES

REPO = os.path.abspath(os.path.join(HERE, *([".."] * 8)))
SUBS = os.path.join(REPO, "protocols", "substreams", "base-flamm", "testdata")
SIM = os.path.join(os.path.dirname(HERE), "snapshots")
SWAP_TOPIC = "0x" + keccak256(b"Swap(address,address,bool,uint256,uint256,uint256,uint256,uint256)").hex()
DEPOSIT_TOPIC = "0x" + keccak256(b"Deposit(address,address,uint256,uint256)").hex()
POOL = "0xc0fdcb1799ccc2cebaa1fe247157b0df33d57572"


def gz(raw):
    buf = io.BytesIO()
    with gzip.GzipFile(fileobj=buf, mode="wb", mtime=0) as f:
        f.write(raw)
    return buf.getvalue()


def words(data):
    d = bytes.fromhex(data[2:])
    return [int.from_bytes(d[i:i + 32], "big") for i in range(0, len(d), 32)]


def main():
    seed = json.load(open(os.path.join(HERE, "out", "stages", "seed_51154965.json")))
    stages = []
    grids = {}
    swaps = []
    deposits = []
    for kind, block, hint, created, want_grids in STAGES:
        st = json.load(open(os.path.join(HERE, "out", "stages", "%d.json" % block)))
        assert st["block"] == block and st["kind"] == kind
        if "grids" in st:
            grids[str(block)] = st["grids"]  # kept in both fixtures: the yaml check reads them here
        else:
            st.pop("state_after")
        st.pop("feed_logs", None)
        if "tx" in st:
            others = []
            mpath = os.path.join(HERE, "out", "stages", "morpho_%d.json" % block)
            if os.path.exists(mpath):
                others = [e for e in json.load(open(mpath))["events"] if not e["own"]]
            for l in st["tx"]["logs"]:
                if l["address"].lower() == POOL and l["topics"][0] == SWAP_TOPIC:
                    ws = words(l["data"])
                    inp = st["tx"]["input"]
                    amount_in = None
                    if inp[:10] == "0x1a019e37":  # FLAMMSwapAdapter.swap(tokenIn, tokenOut, amountIn, minOut, to, deadline)
                        amount_in = str(int(inp[10 + 64 * 2:10 + 64 * 3], 16))
                    swaps.append({"block": block, "tx": st["tx"]["hash"], "tx_index": st["tx"]["index"],
                                  "pool_asset_in": bool(ws[0]), "amount_in_used": str(ws[1]), "amount_out": str(ws[2]),
                                  "fee_out": str(ws[3]), "fee_wad": str(ws[4]), "spot_after_wad": str(ws[5]),
                                  "amount_in": amount_in, "other_morpho_events": others})
                if l["address"].lower() == POOL and l["topics"][0] == DEPOSIT_TOPIC:
                    ws = words(l["data"])
                    deposits.append({"block": block, "tx": st["tx"]["hash"], "assets": str(ws[0]), "shares": str(ws[1]),
                                     "other_morpho_events": others})
        stages.append(st)
    blocks = {
        "note": "Real Base data of the base-flamm end-to-end replay (src/e2e_tests.rs), read from https://mainnet.base.org "
                "with eth_getStorageAt, eth_getBlockByNumber, eth_getTransactionByHash, eth_getTransactionReceipt and "
                "eth_getCode (no debug_*). `seed` is every tracked word at initialBlock - 1 (51154965). Each stage is one "
                "block: `writes` are the block's own storage diffs over the tracked words (eth_getStorageAt at block - 1 "
                "vs block; for a `catchup` stage the net diff since `catchup_from`), `catchup_writes` the net diff of "
                "the blocks between `catchup_from` and this block's parent (`header_before`), `tx` the transaction of "
                "interest with its receipt logs, `codes` the runtime code of the contracts it created, `state_after` "
                "(pinned blocks) every tracked word after the block. Generated by fetch.py, morpho_events.py and pack.py "
                "of crates/tycho-simulation/src/evm/protocol/flamm/testdata/gen.",
        "seed_block": 51154965,
        "seed": seed["state"],
        "stages": stages,
    }
    grids_out = {
        "note": "The chain's answers at the pinned blocks of the end-to-end replay: eth_call at each block of "
                "pool.previewSwap / previewLever on the recorded sizes (return words or revert data), the largest "
                "fully consumed size per direction (doubling then bisection, every probe a row) and EverlongHook.spot; "
                "plus the pool's settled swaps and deposits decoded from their receipts (Swap: poolAssetIn, "
                "amountInUsed, amountOut, feeOut, feeWad, spotAfterWad; amount_in from the adapter calldata when the "
                "swap went through FLAMMSwapAdapter.swap; other_morpho_events: the Morpho Blue events of the venue's "
                "market emitted by the block's other transactions, from eth_getLogs, so the market totals the block "
                "left can be reconstructed from the pool's own settlement).",
        "grids": grids,
        "swaps": swaps,
        "deposits": deposits,
    }
    outs = [(os.path.join(SUBS, "e2e_blocks.json.gz"), blocks), (os.path.join(SIM, "e2e_grids.json.gz"), grids_out)]
    for path, obj in outs:
        raw = json.dumps(obj, sort_keys=True, separators=(",", ":")).encode()
        stored = gz(raw)
        open(path, "wb").write(stored)
        print(path, "raw", len(raw), "gz", len(stored), "sha256(gz)", hashlib.sha256(stored).hexdigest(),
              "sha256(raw)", hashlib.sha256(raw).hexdigest())
    print("swaps", len(swaps), "deposits", len(deposits), "grids", sorted(grids))


if __name__ == "__main__":
    main()
